text:
.autocomplete-row-item {
  /* :::: autocomplete icons :::: */
  & > autocomplete-row-item {
    padding-inline-start: 20px;
    background-position: 3px center;
    background-repeat: no-repeat;
    -moz-context-properties: fill, stroke;
    fill: color-mix(in srgb, currentColor 20%, transparent);
    stroke: currentColor;

    &:-moz-locale-dir(rtl) {
      background-position-x: calc(100% - 3px);
    }
  }

  &[originaltype="local-abook"] > autocomplete-row-item {
    background-image: var(--icon-address-book);
  }

  &[originaltype="remote-abook"] > autocomplete-row-item {
    background-image: var(--icon-globe);
  }

  &[originaltype="remote-err"] > autocomplete-row-item {
    background-image: var(--icon-error-circle);
  }

  &[originaltype="subscribed-news-abook"] > autocomplete-row-item {
    background-image: var(--icon-newsletter);
  }
}
